from collections import deque
from metro import metro          # the graph we just built

def stops_from(graph, start):
    dist = {start: 0}
    queue = deque([start])
    while queue:
        station = queue.popleft()
        for nxt in graph[station]:
            if nxt not in dist:              # first visit = fewest stops
                dist[nxt] = dist[station] + 1
                queue.append(nxt)
    return dist

print("stops  station")
for station, n in stops_from(metro, "Rajiv Chowk").items():
    print(f"{n:>5}  {station}")

