from collections import deque
from metro import metro

def shortest_route(graph, start, goal):
    parent = {start: None}       # station -> the station we reached it from
    queue = deque([start])
    while queue:
        station = queue.popleft()
        if station == goal:
            route = []
            while station is not None:
                route.append(station)
                station = parent[station]
            return route[::-1]
        for nxt in graph.get(station, []):
            if nxt not in parent:
                parent[nxt] = station
                queue.append(nxt)
    return None

print(shortest_route(metro, "Kashmere Gate", "Hauz Khas"))

