class Node:
    def __init__(self, value):
        self.value, self.left, self.right = value, None, None

def insert(node, value):
    if node is None:
        return Node(value)
    if value < node.value:
        node.left = insert(node.left, value)
    else:
        node.right = insert(node.right, value)
    return node

def in_order(node):              # left subtree, node, right subtree
    if node is None:
        return []
    return in_order(node.left) + [node.value] + in_order(node.right)

root = None
for v in [50, 30, 70, 20, 40, 60, 80]:
    root = insert(root, v)
print(in_order(root))
print("root:", root.value, "| left:", root.left.value, "| right:", root.right.value)

tree = (1, (2, (4, None, None), (5, None, None)), (3, None, None))

def pre_order(node):
    if node is None:
        return []
    value, left, right = node
    return [value] + pre_order(left) + pre_order(right)

print(pre_order(tree))

from functools import lru_cache

calls = 0
def ways_naive(n):            # 1 or 2 steps at a time
    global calls
    calls += 1
    if n <= 1:
        return 1
    return ways_naive(n - 1) + ways_naive(n - 2)

@lru_cache(maxsize=None)
def ways_memo(n):
    if n <= 1:
        return 1
    return ways_memo(n - 1) + ways_memo(n - 2)

print(ways_naive(25), "ways,", calls, "calls without memo")
print(ways_memo(25), "ways,", ways_memo.cache_info().misses, "calls with memo")
print(ways_memo(200))

def ways_to_pay(amount, coins):
    table = [1] + [0] * amount        # table[a] = ways to pay a rupees
    for coin in coins:
        for a in range(coin, amount + 1):
            table[a] += table[a - coin]
    return table

table = ways_to_pay(10, [1, 2, 5])
print("ways for ₹0 to ₹10:", table)
print("ways to pay ₹10 with ₹1, ₹2 and ₹5 coins:", table[10])

